API Gateway / Load Balancer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("API Gateway / Load Balancer", "API Gateway / Load Balancer") {
    Component(Amazon_API_Gateway, "Amazon API Gateway", "AWS API Gateway", "Manages API routing, JWT validation via cached JWKS, and rate-limiting.")
    Component(Application_Load_Balancer, "Application Load Balancer", "AWS ALB", "Distributes incoming dynamic API traffic across backend microservices.")
    Component(AWS_WAF_and_Shield, "AWS WAF and Shield", "AWS WAF / AWS Shield", "Provides automated OWASP Top-10 mitigations, rate-based rules, and DDoS protection.")
}

Rel(Amazon_API_Gateway, Application_Load_Balancer, "Routes and balances validated API requests", "HTTPS")
Rel(AWS_WAF_and_Shield, Amazon_API_Gateway, "Inspects and filters incoming traffic for security threats", "HTTPS")
@enduml

Review Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Review Service", "Review Service") {
    Component("Review Service API Controller", "Review Service API Controller", "Spring Boot / Java", "Handles incoming HTTP requests for customer reviews and moderation.")
    Component("Review Processing Service", "Review Processing Service", "Java / Spring", "Business logic processing for reviews, ratings, and content moderation workflows.")
    Component("Review Data Repository", "Review Data Repository", "JDBC / Spring Data JPA", "Manages persistence and retrieval of review data from Amazon RDS PostgreSQL.")
}

System_Ext("Amazon SQS / SNS", "Amazon SQS / SNS", "Messaging infrastructure")

Rel("Review Service API Controller", "Review Processing Service", "Delegates business logic to", "")
Rel("Review Processing Service", "Review Data Repository", "Persists review data via", "JDBC / Spring Data JPA")
Rel("Review Processing Service", "Amazon SQS / SNS", "Publishes asynchronous review events using", "AWS SQS/SNS protocol")

@enduml
